impl Solution{pub fn my_atoi(s:String)->i32{let b=s.as_bytes();let(mut i,mut sign,mut r)=(0usize,1i32,0i32);while i<b.len()&&b[i]==b' '{i+=1;}if i<b.len()&&(b[i]==b'+'||b[i]==b'-'){if b[i]==b'-'{sign=-1;}i+=1;}while i<b.len()&&b[i].is_ascii_digit(){let d=(b[i]-b'0')as i32;i+=1;if sign>0{if r>(i32::MAX-d)/10{return i32::MAX;}r=r*10+d;}else{if r<(i32::MIN+d)/10{return i32::MIN;}r=r*10-d;}}r}}
